import type { Test } from './Test';
/**
 * One entry in a suite's `tests` list: either a bare `Test(...)` reference/sys_id (runs with
 * `abortOnFailure: false`), or an object naming the test with an `abortOnFailure` override.
 */
type TestSuiteEntry = ReturnType<typeof Test> | string | {
    /** The test to include in this suite. Accepts a `Test(...)` reference or its raw sys_id. */
    test: ReturnType<typeof Test> | string;
    /**
     * Stop running the rest of the suite's tests immediately if this one fails. Defaults to
     * `false`. Ignored by ATF's cloud/parallel test runner, which always runs every test in
     * the suite regardless of this setting — informational only, since triggering or running
     * suites is outside this API's scope.
     */
    abortOnFailure?: boolean;
    /**
     * Pins this entry's numeric `order` instead of deriving it from array position.
     * Use to preserve existing custom/gapped order values (100, 200, 300, ...) when
     * adopting Fluent for a suite that already has them. Entries without this still
     * derive order from position; pinned and derived entries can mix freely.
     * Collisions with another entry's final order trigger a build-time hint, since
     * ATF doesn't guarantee run order between ties.
     */
    order?: number;
};
export type TestSuite = Now.Internal.WithIdAndMetadata<{
    /** Suite name, shown in the ATF Test Suites list and picker. */
    name: string;
    /** Whether the suite is available to run. Defaults to `true`. */
    active?: boolean;
    /** Description of what this suite covers. */
    description?: string;
    /**
     * The tests that belong to this suite, in run order — order comes from each entry's position
     * in this array by default (matching how `Test(...)`'s own steps derive order), not a separate
     * authored field. Use the object form (`{ test, abortOnFailure, order }`) to stop the suite
     * early if a specific test fails, or to pin a specific numeric `order` (an escape hatch for
     * preserving custom/gapped order values already set on the instance).
     */
    tests?: readonly TestSuiteEntry[];
    /**
     * Encoded query against `sys_atf_test` used to dynamically determine this suite's membership
     * (maps to `sys_atf_test_suite.input_filter`). ATF evaluates this filter and keeps
     * `sys_atf_test_suite_test` membership rows in sync with the matching tests whenever the
     * suite is saved on the instance — this sync happens on the platform, not during a Fluent
     * build. Combining this with an explicit `tests` list is allowed by the platform, but the two
     * mechanisms can conflict: a manually-listed test that doesn't match `testFilter` may be
     * removed the next time the suite is saved on the instance.
     */
    testFilter?: string;
    /**
     * Parent suite to nest this suite under (maps to `sys_atf_test_suite.parent`). Accepts a
     * `TestSuite(...)` reference or a raw sys_id. When passed as a `TestSuite(...)` reference, the
     * parent must already be declared/constructed before this suite references it (normal
     * declare-before-use), which structurally rules out a cycle. A raw sys_id string that happens
     * to equal this suite's own `$id` is rejected with a build-time error; a longer cycle built
     * from raw sys_id strings across multiple suites is not statically detected by Fluent and is
     * instead caught by the platform when the suite is saved on the instance.
     */
    parent?: TestSuite | string;
}>;
/**
 * Creates an Automated Test Framework test suite (`sys_atf_test_suite`) — a named, orderable
 * collection of `Test(...)` records, optionally nested under a parent suite. Authoring only:
 * Fluent produces the suite/membership metadata; running suites (on-demand, scheduled, or via
 * CI/CD) is done through ATF's existing UI, scheduler, and CI/CD integration, not through Fluent.
 *
 * @see https://docs.servicenow.com/csh?topicname=atf-test-suite-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **name** - suite name
 *   * **active**? - whether the suite is enabled
 *   * **description**? - suite description
 *   * **tests**? - tests that are direct members of this suite, in execution order
 *   * **testFilter**? - encoded query against `sys_atf_test` for dynamic, filter-driven membership
 *   * **parent**? - the parent suite to nest this suite under
 */
export declare function TestSuite(config: TestSuite): TestSuite;
export {};
